const fields=['text','value','checked','visible','enabled','texture','color','opacity','ariaLabel','tooltip'];
export function renderWidgetRowFields(editor,data){
 const inspector=editor.element.querySelector('.ui-properties'),node=editor.doc.data.nodes.find(node=>node.id===editor.selected);inspector?.querySelector('[data-ui-row-fields]')?.remove();if(!inspector||!['ListView','TreeView'].includes(node?.type))return;
 const section=editor.document.createElement('section');section.dataset.uiRowFields='';const title=editor.document.createElement('h3');title.textContent='행 위젯';section.append(title);
 const mode=editor.document.createElement('select');mode.setAttribute('aria-label','목록 선택 방식');for(const [value,text]of [['none','선택 안 함'],['single','단일 선택'],['multiple','다중 선택']]){const option=editor.document.createElement('option');option.value=value;option.textContent=text;mode.append(option);}mode.value=node.properties.selectionMode||'single';mode.onchange=event=>{event.stopPropagation();editor.edit(next=>{const p=next.nodes.find(n=>n.id===node.id).properties;p.selectionMode=mode.value;p.selectedIndices='[]';p.selectedItemIds='[]';p.selectedIndex=-1;p.selectedItemId='';p.value=-1;});};section.append(mode);
 for(const [key,text]of [['rowWriteback','행 입력을 자료에 반영'],...node.type==='ListView'?[['reorderable','항목 순서 변경']]:[]]){const row=editor.document.createElement('label'),input=editor.document.createElement('input');input.type='checkbox';input.checked=node.properties[key]||false;input.setAttribute('aria-label',text);input.onchange=event=>{event.stopPropagation();editor.edit(next=>{next.nodes.find(n=>n.id===node.id).properties[key]=input.checked;});};row.append(input,text);section.append(row);}
 const select=editor.document.createElement('select');select.setAttribute('aria-label','목록 행 위젯');for(const file of [{path:'',name:'기본 텍스트'},...editor.files().filter(file=>file.kind==='widget'&&file.path!==editor.doc.path)]){const option=editor.document.createElement('option');option.value=file.path;option.textContent=file.name;select.append(option);}select.value=node.properties.rowWidget||'';select.onchange=event=>{event.stopPropagation();editor.edit(next=>{const target=next.nodes.find(n=>n.id===node.id);target.properties.rowWidget=select.value;target.properties.rowBindings='{}';});};section.append(select);
 const template=data.nodes.find(n=>n.id===node.id)?.rowTemplate,map=JSON.parse(node.properties.rowBindings||'{}');
 const write=(name,key,path)=>editor.edit(next=>{const target=next.nodes.find(n=>n.id===node.id),bindings=JSON.parse(target.properties.rowBindings||'{}');if(path){bindings[name]??={};bindings[name][key]=path;}else{delete bindings[name]?.[key];if(!Object.keys(bindings[name]||{}).length)delete bindings[name];}target.properties.rowBindings=JSON.stringify(bindings);});
 for(const [name,properties]of Object.entries(map))for(const [key,path]of Object.entries(properties)){const row=editor.document.createElement('label'),input=editor.document.createElement('input'),remove=editor.document.createElement('button');row.textContent=name+' · '+key;input.value=path;input.setAttribute('aria-label','행 자료 '+name+' '+key);input.onchange=event=>{event.stopPropagation();write(name,key,input.value);};remove.textContent='×';remove.title='바인딩 삭제';remove.onclick=event=>{event.stopPropagation();write(name,key,'');};row.append(input,remove);section.append(row);}
 if(template){const name=editor.document.createElement('select'),key=editor.document.createElement('select'),path=editor.document.createElement('input'),add=editor.document.createElement('button');name.setAttribute('aria-label','행 요소');key.setAttribute('aria-label','행 속성');path.setAttribute('aria-label','행 자료 경로');path.placeholder='name / stats.hp / $index';for(const node of template.nodes){const option=editor.document.createElement('option');option.value=node.name;option.textContent=node.name;name.append(option);}for(const value of fields){const option=editor.document.createElement('option');option.value=value;option.textContent=value;key.append(option);}add.textContent='바인딩 추가';add.onclick=event=>{event.stopPropagation();if(path.value)write(name.value,key.value,path.value);};section.append(name,key,path,add);}
 const identity=inspector.querySelector(':scope > section');inspector.insertBefore(section,identity?.nextSibling||null);
}
